PUBLIC BRIEF: {"buyer":"Paradigm Initiative","exclusions":["This is an employment-role normalization, not authorization to replace a hire or perform commissioned consulting work; no application, hiring decision or external outreach is authorized.","Website/social accounts, internal calendars, communications policies, approved response guidelines, organizational source content and private analytics were not supplied.","Experimental agent_draft annotations cover only proposed content, plans or research briefs; no live posting, autonomous ongoing monitoring, advertising spend or guaranteed media/engagement outcome is authorized."],"id":"paradigm-initiative-bilingual-communications-assistant-2025","requirements":[{"brick":"draft","id":"R1","owner":"blocked_private_input","text":"Help draft press releases and statements, circulate them to PIN's media network and publish them on its website when due."},{"brick":"plan","id":"R2","owner":"agent_draft","text":"Assist in developing communications and social-media plans."},{"brick":"plan","id":"R3","owner":"human_required","text":"Support execution of communications strategies in collaboration with the communications team, other departments and stakeholders."},{"brick":"draft","id":"R4","owner":"agent_draft","text":"Create engaging English- and French-language content for PIN's social-media channels."},{"brick":"transform","id":"R5","owner":"blocked_private_input","text":"Translate organizational content between French and English."},{"brick":"monitor","id":"R6","owner":"agent_draft","text":"Support media monitoring and track news relevant to PIN's work."},{"brick":"notify","id":"R7","owner":"blocked_private_input","text":"Under the Officer's direction, schedule and publish daily posts on Twitter, LinkedIn, Facebook, Instagram and TikTok, following the communications/social calendars, stated entry deadlines and communications policy."},{"brick":"monitor","id":"R8","owner":"blocked_private_input","text":"Monitor social comments and messages, escalate critical issues to the Officer and answer routine inquiries using pre-approved guidelines."},{"brick":"report","id":"R9","owner":"blocked_private_input","text":"Collect raw platform analytics weekly and compile them in a standardized report for the Officer's review."},{"brick":"draft","id":"R10","owner":"agent_draft","text":"Prepare campaign visuals and multimedia, including images, simple graphics and short videos."},{"brick":"review","id":"R11","owner":"human_required","text":"Proofread communications materials and coordinate their production."},{"brick":"retrieve","id":"R12","owner":"agent_draft","text":"Research and gather information and data for content and communications strategy."},{"brick":"notify","id":"R13","owner":"human_required","text":"Pitch and secure coverage for PIN in at least three media outlets or publications each quarter."},{"brick":"report","id":"R14","owner":"blocked_private_input","text":"Provide detailed, accurate activity reports to the Communications Manager for timely publication when required."},{"brick":"monitor","id":"R15","owner":"human_required","text":"Work toward the stated target of increasing engagement across PIN's social platforms by 5% each quarter through positive mentions, shares, likes and other interactions."}],"source_url":"https://paradigmhq.org/working-zone/vacancy-bilingual-communications-assistant-english-french/","summary":"Historical full-time, hybrid English/French communications-assistant job posting, not a consulting RFP. Duties cover bilingual communications, publishing, social-media operations, research and reporting. The listed countries are Kenya, Senegal, Cameroon, Zambia and Zimbabwe; applications closed November 11, 2025, with earlier filling possible.","title":"Vacancy: Bilingual Communications Assistant (English/French)"}
